export interface CustomElementEvent {
  name: string;
  type?: string;
  description: string;
}

export interface CustomElementMethod {
  name: string;
  description: string;
  signature: string;
}

export interface CustomElementProperty {
  name: string;
  type: string;
  default?: string;
  defaultValue?: string;
  description: string;
}

export interface CustomElementSlot {
  name: string;
  description: string;
}

export interface CustomElementValueAccessor {
  selector: string;
  event: string;
  targetAttr: string;
  type: string;
}

export interface CustomElementComponent {
  name: string;
  properties?: Array<CustomElementProperty>;
  methods?: Array<CustomElementMethod>;
  events?: Array<CustomElementEvent>;
  slots?: Array<CustomElementSlot>;
  valueAccessors?: Array<CustomElementValueAccessor>;
  deprecation?: string;
}

export interface CustomElementMetadata {
  tags: Array<CustomElementComponent>;
}
